-- Nexgen OS — country pack XA (Examplia), version 0.1.0.
--
-- Generated by `nexgen-os pack build xa` from packs/xa/: pack.json, identifiers.json, sources.json, grid.json, defaults.json.
-- Do not edit: change the pack and build again. `nexgen-os pack check --all`
-- refuses a seed that is not the exact output of its pack.
--
-- file           core/seed/10_pack_xa.sql
-- checksum       sha256:1f4d471b52d59e4015c56f2956356a7720ea75aa89abad13022e6b0d510ddac5
-- certification  reviewed, A grid engineer of the fixture, for the tests of the toolchain, 2026-10-19
-- schema_min     0.2.0
-- modules        grid
--
-- Every row is upserted by its natural key, so the file can be applied again
-- and a new version of the pack reaches an installation holding an older one.
-- A vocabulary row is updated only where this pack published it. A value is
-- dated and never edited: the database refuses a value that differs from the
-- one it holds for the same property, region and valid_from (value_edited).
-- Nothing is deleted. Apply the file in one transaction, as the installer does.

set search_path = nexgen, public, extensions;

-- sources: 3. The registers, services and texts the country's data and values come from.
insert into sources (code, name, description, kind, base_url, docs_url, auth, countries, regions, license, attribution, retention_days, redistributable, published_by) values
  ('xa_address_register', 'Address register of the North', null, 'api', 'https://example.org/addresses', 'https://example.org/addresses/docs', 'none', array['XA']::text[], array['XA-N']::text[], 'CC-BY-4.0', 'Address register of the North', null, true, 'pack:xa'),
  ('xa_grid_code', 'Grid code of Examplia', null, 'text', 'https://example.org/grid-code', null, 'none', array['XA']::text[], '{}'::text[], 'public text', null, null, true, 'pack:xa'),
  ('xa_statistics', 'Statistics office of Examplia', null, 'file', 'https://example.org/statistics', null, 'none', array['XA']::text[], '{}'::text[], 'CC-BY-4.0', null, 30, false, 'pack:xa')
on conflict (code) do update set
  name            = excluded.name,
  description     = excluded.description,
  kind            = excluded.kind,
  base_url        = excluded.base_url,
  docs_url        = excluded.docs_url,
  auth            = excluded.auth,
  countries       = excluded.countries,
  regions         = excluded.regions,
  license         = excluded.license,
  attribution     = excluded.attribution,
  retention_days  = excluded.retention_days,
  redistributable = excluded.redistributable
where sources.published_by = excluded.published_by;

-- id_schemes: 2. The identifiers the country issues; a value of external_ids or meters matches the pattern.
insert into id_schemes (code, name, description, pattern, url_template, source_code, published_by) values
  ('xa_metering_point', 'Metering point number', 'Issued by the distribution operator of the connection.', '^XA[0-9]{8}$', null, null, 'pack:xa'),
  ('xa_municipality', 'Municipality code', null, '^[0-9]{5}$', 'https://example.org/municipality/{value}', 'xa_statistics', 'pack:xa')
on conflict (code) do update set
  name         = excluded.name,
  description  = excluded.description,
  pattern      = excluded.pattern,
  url_template = excluded.url_template,
  source_code  = excluded.source_code
where id_schemes.published_by = excluded.published_by;

-- countries: who the country is, and which version of its pack this installation holds.
insert into countries (code, name, currency, languages, time_zones, region_level, postal_code_pattern, municipality_scheme, pack_version, pack_checksum, published_by) values
  ('XA', 'Examplia', 'XTS', array['en']::text[], array['Etc/UTC', 'Etc/GMT-1']::text[], 'province', '^[0-9]{4}$', 'xa_municipality', '0.1.0', 'sha256:1f4d471b52d59e4015c56f2956356a7720ea75aa89abad13022e6b0d510ddac5', 'pack:xa')
on conflict (code) do update set
  name                = excluded.name,
  currency            = excluded.currency,
  languages           = excluded.languages,
  time_zones          = excluded.time_zones,
  region_level        = excluded.region_level,
  postal_code_pattern = excluded.postal_code_pattern,
  municipality_scheme = excluded.municipality_scheme,
  pack_version        = excluded.pack_version,
  pack_checksum       = excluded.pack_checksum;

-- regions: 3 at the level province and above, parents first.
insert into regions (code, country, name, parent, time_zone, published_by) values
  ('XA-N', 'XA', 'North', null, null, 'pack:xa'),
  ('XA-S', 'XA', 'South', null, 'Etc/GMT-1', 'pack:xa'),
  ('XA-NW', 'XA', 'North-West', 'XA-N', null, 'pack:xa')
on conflict (code) do update set
  country   = excluded.country,
  name      = excluded.name,
  parent    = excluded.parent,
  time_zone = excluded.time_zone
where regions.published_by = excluded.published_by;

-- grid.operators: 2. Who runs the grid, where, and which metering identifier they issue.
insert into grid.operators (code, name, kind, country, regions, coverage, website, data_hub_url, identifier_scheme, description, published_by) values
  ('xa_north_dso', 'Distribution operator of the North', 'dso', 'XA', array['XA-N', 'XA-NW']::text[], null, null, 'https://example.org/north/hub', 'xa_metering_point', null, 'pack:xa'),
  ('xa_tso', 'Transmission operator of Examplia', 'tso', 'XA', '{}'::text[], null, 'https://example.org/tso', null, null, null, 'pack:xa')
on conflict (code) do update set
  name              = excluded.name,
  kind              = excluded.kind,
  country           = excluded.country,
  regions           = excluded.regions,
  coverage          = excluded.coverage,
  website           = excluded.website,
  data_hub_url      = excluded.data_hub_url,
  identifier_scheme = excluded.identifier_scheme,
  description       = excluded.description
where operators.published_by = excluded.published_by;

-- defaults: 7 value(s), 1 of them for a region. What parameter_of() answers
-- for a participant of the country when nothing nearer gives a value.
do $seed$
declare
  refused text;
begin
  with pack (property_code, region, value, unit, valid_from, valid_to, source_code, reference) as (
    values
      ('connection_max_power_lv'::text, null::text, '250'::jsonb, 'KiloW'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 7, table 1'::text),
      ('grid_co2_factor'::text, null::text, '0.12'::jsonb, 'KiloGM-PER-KiloW-HR'::text, '2026-01-01'::date, null::date, 'xa_statistics'::text, 'Yearly balance 2025, table 3'::text),
      ('metering_step'::text, null::text, '"PT30M"'::jsonb, 'ISO8601-duration'::text, '2020-01-01'::date, '2025-01-01'::date, 'xa_grid_code'::text, 'Article 12'::text),
      ('metering_step'::text, null::text, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2025-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 12, as amended'::text),
      ('offpeak_hours'::text, null::text, null::jsonb, 'hours'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 40: set by each supply contract'::text),
      ('sharing_max_distance_m'::text, 'XA-S'::text, '2000'::jsonb, 'M'::text, '2023-07-01'::date, null::date, 'xa_grid_code'::text, 'Article 31'::text),
      ('voltage_levels'::text, null::text, '[{"code":"lv","name":"Low voltage","min_kv":0,"max_kv":1},{"code":"mv","name":"Medium voltage","min_kv":1,"max_kv":36},{"code":"hv","name":"High voltage","min_kv":36,"max_kv":400}]'::jsonb, 'KiloV'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 2'::text)
  ),
  problems (problem) as (
    select format('property_unknown: %s is not a property_defs code', p.property_code)
      from pack p
     where not exists (select 1 from property_defs d where d.code = p.property_code)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.property_code, q.unit, p.unit)
      from pack p
      join property_defs d on d.code = p.property_code
      join quantities q on q.code = d.quantity_code
     where q.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.property_code, coalesce(' (' || p.region || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'XA' and x.property_code = p.property_code
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (property_code, country, region, value, valid_from, valid_to, source_code, reference, published_by)
    select p.property_code, 'XA', p.region, p.value, p.valid_from, p.valid_to, p.source_code, p.reference, 'pack:xa'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, property_code, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
